mapper.sql:
o.tenant_id=#{tenantId}
AND EXISTS (SELECT 1 FROM merchant_store s_scope WHERE s_scope.id=o.store_id
  AND s_scope.tenant_id=#{tenantId} AND s_scope.status='ACTIVE' AND s_scope.deleted=0
  AND EXISTS (SELECT 1 FROM sys_user u_scope WHERE u_scope.id=#{userId}
    AND u_scope.tenant_id=#{tenantId} AND u_scope.status='ACTIVE' AND u_scope.deleted=0)
  AND (
    EXISTS (SELECT 1 FROM sys_user_role ur_scope JOIN sys_role r_scope ON r_scope.id=ur_scope.role_id
      WHERE ur_scope.tenant_id=#{tenantId} AND ur_scope.user_id=#{userId} AND r_scope.tenant_id=#{tenantId}
        AND r_scope.role_scope='TENANT' AND r_scope.status='ACTIVE' AND r_scope.deleted=0
        AND r_scope.role_code IN ('MERCHANT_ADMIN','FINANCE_OPERATOR','WAREHOUSE_OPERATOR','CUSTOMER_SERVICE_OPERATOR'))
    OR (
      EXISTS (SELECT 1 FROM sys_user_role ur_scope JOIN sys_role r_scope ON r_scope.id=ur_scope.role_id
        WHERE ur_scope.tenant_id=#{tenantId} AND ur_scope.user_id=#{userId} AND r_scope.tenant_id=#{tenantId}
          AND r_scope.role_code='MERCHANT_OPERATOR' AND r_scope.role_scope='TENANT'
          AND r_scope.status='ACTIVE' AND r_scope.deleted=0)
      AND EXISTS (SELECT 1 FROM sys_user_store_scope uss_scope
        WHERE uss_scope.tenant_id=#{tenantId} AND uss_scope.user_id=#{userId}
          AND uss_scope.store_id=o.store_id AND uss_scope.status='ACTIVE')
    )
  )
)
AND o.store_id=#{storeId}

mapper.select:
SELECT o.id AS order_id, o.order_no, o.store_id, s.store_name, o.destination_country AS destination, o.current_status AS order_status, po.lifecycle_status AS label_status, o.chargeable_weight, o.current_fee AS estimated_fee, o.currency, COALESCE(po.tracking_no, obr.tracking_no) AS sf_tracking_no, o.updated_at FROM shipment_order o JOIN merchant_store s ON s.id=o.store_id AND s.tenant_id=o.tenant_id LEFT JOIN provider_order po ON po.tenant_id=o.tenant_id AND po.shipment_order_id=o.id LEFT JOIN warehouse_outbound_record obr ON obr.tenant_id=o.tenant_id AND obr.shipment_order_id=o.id WHERE AND o.updated_at >= #{from} AND o.updated_at < #{to}
ORDER BY o.created_at ASC, o.id ASC ORDER BY o.created_at DESC, o.id DESC ORDER BY o.updated_at ASC, o.id ASC ORDER BY o.updated_at DESC, o.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT item_id,resource_type,resource_id,order_id,store_id,display_no,status,source,occurred_at
FROM () metric_fact
ORDER BY occurred_at DESC,item_id DESC LIMIT #{limit} OFFSET #{offset}
